public static class ImageResizer
{
    [FunctionName("ResizeImage")]
    public static async Task Run(
        [BlobTrigger("uploads/{name}", Source = BlobTriggerSource.Event, Connection = "AzureWebJobsStorage")] Stream inputStream,
        string name,
        [Blob("thumbnails/{name}", FileAccess.Write)] Stream outputStream,
        ILogger log)
    {
        log.LogInformation($"Resizing image: {name}");

        using var image = await Image.LoadAsync(inputStream);
        image.Mutate(x => x.Resize(150, 150));
        await image.SaveAsync(outputStream);
    }
}
